// Generated from src/registry/sources/control-ui/recipes/badge.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const badgeKnobs = [
  "--cui-badge-icon",
  "--cui-badge-radius",
  "--cui-badge-background",
  "--cui-badge-foreground",
  "--cui-badge-border-color",
  "--cui-badge-border-width",
  "--cui-badge-font-family",
  "--cui-badge-font-size",
  "--cui-badge-font-weight",
] as const;
export type BadgeKnobStyle = Partial<Record<(typeof badgeKnobs)[number], string>>;

@layer components {
  :where([data-control-family="badge"][data-slot="root"]) {
    gap: calc(var(--spacing) * 1);
    padding: calc(var(--spacing) * 0.5) calc(var(--spacing) * 2);
    overflow: hidden;
    --cui-badge-icon: 1em;
    --cui-badge-radius: var(--radius-control);
    --cui-badge-background: var(--_badge-color-background);
    --cui-badge-foreground: var(--_badge-color-foreground);
    --cui-badge-border-color: transparent;
    --cui-badge-border-width: 1px;
    --cui-badge-font-size: var(--text-caption);
    --cui-badge-font-weight: var(--font-weight-medium);
    --cui-badge-font-family: var(--font-body);
    --_badge-color-background: var(--badge-neutral);
    --_badge-color-foreground: var(--badge-neutral-foreground);
    --_badge-color-border: var(--badge-neutral-border);
    --_badge-color-background-hover: var(--badge-neutral-hover);
    --_badge-hover-background: var(--_badge-color-background-hover);
    border-style: solid;
    border-width: var(--cui-badge-border-width);
    border-color: var(--cui-badge-border-color);
    border-radius: var(--cui-badge-radius);
    background: var(--cui-badge-background);
    color: var(--cui-badge-foreground);
    font-family: var(--cui-badge-font-family);
    font-size: var(--cui-badge-font-size);
    font-weight: var(--cui-badge-font-weight);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="badge"][data-slot="root"] > svg) {
    pointer-events: none;
    inline-size: var(--cui-badge-icon);
    block-size: var(--cui-badge-icon);
  }

  :where([data-control-family="badge"][data-slot="root"][data-size="sm"]) {
    --cui-badge-font-size: var(--text-micro);
    block-size: calc(var(--spacing) * 4);
    padding: 0 calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="badge"][data-slot="root"][data-variant="outline"]) {
    --cui-badge-background: transparent;
    --cui-badge-border-color: var(--_badge-color-border);
    --_badge-hover-background: var(--_badge-color-background);
  }

  :where(:is(a, button)[data-control-family="badge"][data-slot="root"]) {
    position: relative;
    overflow: visible;
    cursor: pointer;
  }

  :where(:is(a, button)[data-control-family="badge"][data-slot="root"])::after {
    content: "";
    position: absolute;
    inset: 50% auto auto 50%;
    translate: -50% -50%;
    inline-size: max(100%, var(--target-min));
    block-size: max(100%, var(--target-min));
  }

  @media (pointer: coarse) {
    :where(:is(a, button)[data-control-family="badge"][data-slot="root"])::after {
      block-size: max(100%, var(--touch-target));
    }
  }

  @media (hover: hover) {
    :where(:is(a, button)[data-control-family="badge"][data-slot="root"]:hover:not(:disabled, [data-disabled], [aria-disabled="true"])) {
      background: var(--_badge-hover-background);
    }
  }

  :where([data-control-family="badge"][data-slot="root"]:is(:disabled, [data-disabled], [aria-disabled="true"])) {
    cursor: not-allowed;
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="primary"]) {
    --_badge-color-background: var(--primary);
    --_badge-color-foreground: var(--primary-foreground);
    --_badge-color-border: var(--primary);
    --_badge-color-background-hover: oklch(from var(--primary) calc(l - 0.05) c h);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="primary"][data-variant="outline"]) {
    --_badge-color-background: oklch(from var(--primary) l c h / var(--badge-fill-alpha));
    --_badge-color-foreground: var(--primary-text);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="red"]) {
    --_badge-color-background: var(--badge-red);
    --_badge-color-foreground: var(--badge-red-foreground);
    --_badge-color-border: var(--badge-red-border);
    --_badge-color-background-hover: var(--badge-red-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="orange"]) {
    --_badge-color-background: var(--badge-orange);
    --_badge-color-foreground: var(--badge-orange-foreground);
    --_badge-color-border: var(--badge-orange-border);
    --_badge-color-background-hover: var(--badge-orange-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="yellow"]) {
    --_badge-color-background: var(--badge-yellow);
    --_badge-color-foreground: var(--badge-yellow-foreground);
    --_badge-color-border: var(--badge-yellow-border);
    --_badge-color-background-hover: var(--badge-yellow-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="green"]) {
    --_badge-color-background: var(--badge-green);
    --_badge-color-foreground: var(--badge-green-foreground);
    --_badge-color-border: var(--badge-green-border);
    --_badge-color-background-hover: var(--badge-green-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="blue"]) {
    --_badge-color-background: var(--badge-blue);
    --_badge-color-foreground: var(--badge-blue-foreground);
    --_badge-color-border: var(--badge-blue-border);
    --_badge-color-background-hover: var(--badge-blue-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="purple"]) {
    --_badge-color-background: var(--badge-purple);
    --_badge-color-foreground: var(--badge-purple-foreground);
    --_badge-color-border: var(--badge-purple-border);
    --_badge-color-background-hover: var(--badge-purple-hover);
  }

  :where([data-control-family="badge"][data-slot="root"][data-color="pink"]) {
    --_badge-color-background: var(--badge-pink);
    --_badge-color-foreground: var(--badge-pink-foreground);
    --_badge-color-border: var(--badge-pink-border);
    --_badge-color-background-hover: var(--badge-pink-hover);
  }
}

@property --cui-badge-icon {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-badge-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-badge-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-badge-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-badge-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-badge-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-badge-font-family {
  syntax: "*";
  inherits: true;
}

@property --cui-badge-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-badge-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 400;
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties } from "react";
import type { RenderProp } from "@/components/control-ui/control-props";
import type { BadgeKnobStyle } from "@/components/control-ui/knob-contracts/badge-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export const badgeVariants = ["default", "outline"] as const;

export type BadgeVariant = (typeof badgeVariants)[number];

export const badgeSizes = ["sm", "md"] as const;

export type BadgeSize = (typeof badgeSizes)[number];

export const BADGE_COLORS = ["neutral", "red", "orange", "yellow", "green", "blue", "purple", "pink"] as const;

export type BadgeColor = (typeof BADGE_COLORS)[number] | "primary";

export type BadgeProps = Omit<ComponentProps<"span">, "style"> & {
  variant?: BadgeVariant;
  size?: BadgeSize;
  color?: BadgeColor;
  render?: RenderProp<ComponentProps<"span">>;
  style?: CSSProperties & BadgeKnobStyle;
};

export function Badge({ variant = "default", size = "md", color, render, className, children, ...props }: BadgeProps) {
  const resolvedColor = color ?? "neutral";

  return useRender({
    defaultTagName: "span",
    render,
    props: {
      ...props,
      "data-control-ui": "badge",
      "data-control-family": "badge",
      "data-slot": "root",
      "data-variant": variant,
      "data-size": size,
      "data-color": resolvedColor,
      className: cn("inline-flex w-fit shrink-0 items-center justify-center whitespace-nowrap", className),
      children,
    },
  });
}
